-- ============================================
-- Denterlab — cleaned dental practices (agency's national dentist file)
-- Generated by scripts/denterlab/build.ts — do not edit by hand.
--
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f scripts/denterlab/import.sql
--
-- Fills the existing mission « Denterlab — Cabinets dentaires » (client Denterlab); fails if it is missing.
-- One transaction, safe to re-run. 4 lists:
--   DTL 1 · Cabinets accueillants (déjà appelés, ouverts): 437
--   DTL 2 · Cabinets joints: 917
--   DTL 3 · Cabinets jamais joints: 2423
--   DTL 4 · Cabinets jamais appelés: 2955
-- Exclusion rules are not applied by this file.
-- ============================================

\set ON_ERROR_STOP on
BEGIN;

DO $do$
DECLARE
    v_mission  text;
    v_campaign text;
    v_list     text;
    v_count    integer;
BEGIN
    SELECT m.id INTO v_mission FROM "Mission" m JOIN "Client" c ON c.id = m."clientId"
     WHERE lower(c.name) = 'denterlab' AND m.name = 'Denterlab — Cabinets dentaires' LIMIT 1;
    IF v_mission IS NULL THEN
        RAISE EXCEPTION 'Mission « Denterlab — Cabinets dentaires » not found: import the Denterlab mission first (scripts/missions-2026-11).';
    END IF;
    SELECT id INTO v_campaign FROM "Campaign" WHERE "missionId" = v_mission AND name = 'Denterlab — 3 prothèses d''essai offertes' LIMIT 1;

    -- DTL 1 · Cabinets accueillants (déjà appelés, ouverts) : 437 cabinets
    SELECT id INTO v_list FROM "List" WHERE "missionId" = v_mission AND name = 'DTL 1 · Cabinets accueillants (déjà appelés, ouverts)' LIMIT 1;
    IF v_list IS NULL THEN
        v_list := 'dtllstb66aa691e136878a0d257';
        VALUES (v_list, v_mission, 'DTL 1 · Cabinets accueillants (déjà appelés, ouverts)', 'SUZALI', 'Fichier dentistes France (Google Maps, agence) nettoyé', '{"importType":"sql","tier":"1 · Cabinet accueillant","practices":437}'::jsonb, now());
        IF v_campaign IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'List' AND column_name = 'campaignId') THEN
            EXECUTE 'UPDATE "List" SET "campaignId" = $1 WHERE id = $2' USING v_campaign, v_list;
        END IF;
    END IF;
    SELECT count(*) INTO v_count FROM "Company" WHERE "listId" = v_list;
    IF v_count > 0 THEN
        RAISE NOTICE 'DTL 1 · Cabinets accueillants (déjà appelés, ouverts): already holds % companies, not re-imported', v_count;
    ELSE
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        RAISE NOTICE 'DTL 1 · Cabinets accueillants (déjà appelés, ouverts): 437 cabinets imported';
    END IF;

    -- DTL 2 · Cabinets joints : 917 cabinets
    SELECT id INTO v_list FROM "List" WHERE "missionId" = v_mission AND name = 'DTL 2 · Cabinets joints' LIMIT 1;
    IF v_list IS NULL THEN
        v_list := 'dtllst58fe895084037c202da7d';
        VALUES (v_list, v_mission, 'DTL 2 · Cabinets joints', 'SUZALI', 'Fichier dentistes France (Google Maps, agence) nettoyé', '{"importType":"sql","tier":"2 · Cabinet joint","practices":917}'::jsonb, now());
        IF v_campaign IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'List' AND column_name = 'campaignId') THEN
            EXECUTE 'UPDATE "List" SET "campaignId" = $1 WHERE id = $2' USING v_campaign, v_list;
        END IF;
    END IF;
    SELECT count(*) INTO v_count FROM "Company" WHERE "listId" = v_list;
    IF v_count > 0 THEN
        RAISE NOTICE 'DTL 2 · Cabinets joints: already holds % companies, not re-imported', v_count;
    ELSE
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        RAISE NOTICE 'DTL 2 · Cabinets joints: 917 cabinets imported';
    END IF;

    -- DTL 3 · Cabinets jamais joints : 2423 cabinets
    SELECT id INTO v_list FROM "List" WHERE "missionId" = v_mission AND name = 'DTL 3 · Cabinets jamais joints' LIMIT 1;
    IF v_list IS NULL THEN
        v_list := 'dtllst54d5ec6256c5a30e0ac54';
        VALUES (v_list, v_mission, 'DTL 3 · Cabinets jamais joints', 'SUZALI', 'Fichier dentistes France (Google Maps, agence) nettoyé', '{"importType":"sql","tier":"3 · Jamais joint","practices":2423}'::jsonb, now());
        IF v_campaign IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'List' AND column_name = 'campaignId') THEN
            EXECUTE 'UPDATE "List" SET "campaignId" = $1 WHERE id = $2' USING v_campaign, v_list;
        END IF;
    END IF;
    SELECT count(*) INTO v_count FROM "Company" WHERE "listId" = v_list;
    IF v_count > 0 THEN
        RAISE NOTICE 'DTL 3 · Cabinets jamais joints: already holds % companies, not re-imported', v_count;
    ELSE
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        RAISE NOTICE 'DTL 3 · Cabinets jamais joints: 2423 cabinets imported';
    END IF;

    -- DTL 4 · Cabinets jamais appelés : 2955 cabinets
    SELECT id INTO v_list FROM "List" WHERE "missionId" = v_mission AND name = 'DTL 4 · Cabinets jamais appelés' LIMIT 1;
    IF v_list IS NULL THEN
        v_list := 'dtllst8049bdc2f5cfd2fae9505';
        VALUES (v_list, v_mission, 'DTL 4 · Cabinets jamais appelés', 'SUZALI', 'Fichier dentistes France (Google Maps, agence) nettoyé', '{"importType":"sql","tier":"4 · Jamais appelé","practices":2955}'::jsonb, now());
        IF v_campaign IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'List' AND column_name = 'campaignId') THEN
            EXECUTE 'UPDATE "List" SET "campaignId" = $1 WHERE id = $2' USING v_campaign, v_list;
        END IF;
    END IF;
    SELECT count(*) INTO v_count FROM "Company" WHERE "listId" = v_list;
    IF v_count > 0 THEN
        RAISE NOTICE 'DTL 4 · Cabinets jamais appelés: already holds % companies, not re-imported', v_count;
    ELSE
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        ON CONFLICT (id) DO NOTHING;
        RAISE NOTICE 'DTL 4 · Cabinets jamais appelés: 2955 cabinets imported';
    END IF;

END
$do$;

COMMIT;

-- Check
SELECT l.name AS list, count(DISTINCT co.id) AS cabinets, count(ct.id) AS contacts
FROM "List" l
JOIN "Mission" m ON m.id = l."missionId"
LEFT JOIN "Company" co ON co."listId" = l.id
LEFT JOIN "Contact" ct ON ct."companyId" = co.id
WHERE m.name = 'Denterlab — Cabinets dentaires'
GROUP BY l.name ORDER BY l.name;
